if (box1.max.x < box2.min.x || box1.min.x > box2.max.x ||
    box1.max.y < box2.min.y || box1.min.y > box2.max.y ||
    box1.max.z < box2.min.z || box1.min.z > box2.max.z) {
    return BoxRelation::Separated;
}

// Check for adjacency (boxes touch but don't overlap)
bool adjacent = false;
if (std::abs(box1.max.x - box2.min.x) < 1e-6f ||
    std::abs(box1.min.x - box2.max.x) < 1e-6f ||
    std::abs(box1.max.y - box2.min.y) < 1e-6f ||
    std::abs(box1.min.y - box2.max.y) < 1e-6f ||
    std::abs(box1.max.z - box2.min.z) < 1e-6f ||
    std::abs(box1.min.z - box2.max.z) < 1e-6f) {
    adjacent = true;
}

// Check for overlap in all dimensions
bool overlap = !(box1.max.x < box2.min.x || box1.min.x > box2.max.x) &&
               !(box1.max.y < box2.min.y || box1.min.y > box2.max.y) &&
               !(box1.max.z < box2.min.z || box1.min.z > box2.max.z);

if (overlap) {
    return BoxRelation::Overlapped;
} else if (adjacent) {
    return BoxRelation::Adjacent;
} else {
    return BoxRelation::Separated;
}
